from fractions import Fraction


def weighted_quantile(items, numerator, denominator):
    if denominator <= 0 or numerator < 0 or numerator > denominator:
        raise ValueError("invalid numerator/denominator")

    merged = {}
    for value, weight in items:
        if weight < 0:
            raise ValueError("negative weight")
        if weight == 0:
            continue
        merged[value] = merged.get(value, 0) + weight

    if not merged:
        return None

    total = sum(merged.values())
    if numerator == 0:
        return min(merged)

    threshold = Fraction(total * numerator, denominator)
    cumulative = 0
    for value in sorted(merged):
        cumulative += merged[value]
        if cumulative >= threshold:
            return value
